def second_largest(xs: list[int]) -> int | None:
    uniq = set(xs)
    if len(uniq) < 2:
        return None
    first = second = None
    for v in uniq:
        if first is None or v > first:
            second = first
            first = v
        elif second is None or v > second:
            second = v
    return second
